import heapq


def minCostTransform(start, target, limit, costs):
    add_c, dbl_c, half_c = costs
    INF = float('inf')
    dist = [INF] * (limit + 1)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, x = heapq.heappop(heap)
        if d > dist[x]:
            continue
        if x == target:
            return d
        moves = []
        if x + 1 <= limit:
            moves.append((x + 1, add_c))
        if 2 * x <= limit:
            moves.append((2 * x, dbl_c))
        if x % 2 == 0:
            moves.append((x // 2, half_c))
        for y, c in moves:
            if d + c < dist[y]:
                dist[y] = d + c
                heapq.heappush(heap, (d + c, y))
    return -1
